"""Shared state for videos generated by the NBA performance pipeline."""
import json
import os
import unicodedata


STATE_FILE = os.environ.get(
    "NBA_AGENT_STATE", "processed_performances.json"
)


def load_processed_performances(path: str = STATE_FILE) -> dict:
    """Load date-keyed processed-player entries from the state file."""
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as state_file:
        state = json.load(state_file)
    if not isinstance(state, dict):
        raise ValueError(f"Invalid processed performances state: {path}")
    return state


def save_processed_performances(state: dict, path: str = STATE_FILE) -> None:
    """Write date-keyed processed-player entries to the state file."""
    with open(path, "w", encoding="utf-8") as state_file:
        json.dump(state, state_file, indent=2)


def performance_key(player_name: str, team: str) -> str:
    """Build the same accent-insensitive player/team key used by the agent."""
    normalized_name = "".join(
        character
        for character in unicodedata.normalize("NFD", player_name)
        if unicodedata.category(character) != "Mn"
    )
    return f"{normalized_name}|{team.lower()}"
